lines=lines[start:end]
# Remove PDF page headers / footer lines but retain TOC entries ending in section-page token.
page_re=re.compile(r'\\s+([A-I]\\d+(?:\\s*[–-]\\s*[A-I]\\d+)?)\\s*"'$'"')
bullet_re=re.compile(r'"'^'"\\s*[•·]\\s*(.*?)\\s*"'$'"')
section_marks=[
 ('UNDER-GRADUATE PROGRAMMES','undergraduate','regular'),
 ('POST-GRADUATE PROGRAMMES','postgraduate','regular'),
 ('RESEARCH PROGRAMMES','doctoral','regular'),
 ('DIPLOMA PROGRAMMES','diploma','regular'),
 ('SENIOR SECONDARY SCHOOL CERTIFICATE','certificate','regular'),
 ('BRIDGE COURSE','bridge','regular'),
 ('DIPLOMA PROGRAMMES UNDER CENTRE OF PROFESSIONAL COURSES','diploma','regular'),
 ('DISTANCE AND ONLINE EDUCATION PROGRAMMES','distance','distance and online'),
 ('PART TIME PROGRAMMES','part-time','part-time'),
]
# Map order carefully: first long phrase should win.
section_marks=sorted(section_marks,key=lambda x:len(x[0]),reverse=True)
current_level='undergraduate'; current_mode='regular'; current_name=None; current_spec=None; records=[]
skip_exact={'Particulars','Aligarh Muslim University','Guide to Admissions 2026-27'}
for raw in lines:
    line=raw.replace('\\f','').strip()
    if not line: continue
    # page headers sometimes remain without a page marker
    if line in skip_exact or line.startswith('Aligarh Muslim University') or line.startswith('Particulars'): continue
    hit=None
    for mark,level,mode in section_marks:
        if mark in line and not page_re.search(line):
            hit=(level,mode); break
    if hit:
        current_level,current_mode=hit; current_name=None; current_spec=None; continue
    bm=bullet_re.match(line)
    if bm and current_name:
        spec=bm.group(1).strip()
        records.append((current_name,spec,current_level,current_mode))
        continue
    pm=page_re.search(line)
    if not pm: continue
    name=page_re.sub('',line).strip()
    if not name or name in skip_exact: continue
    # Avoid category/institution labels that happen to end with a page token.
    if name.upper() in {'FACULTY OF ARTS','FACULTY OF COMMERCE','FACULTY OF ENGINEERING & TECHNOLOGY','FACULTY OF INTERNATIONAL STUDIES','FACULTY OF LAW','FACULTY OF LIFE SCIENCES','FACULTY OF MEDICINE','FACULTY OF SCIENCE','FACULTY OF SOCIAL SCIENCES','FACULTY OF THEOLOGY','FACULTY OF UNANI MEDICINE','FACULTY OF AGRICULTURAL SCIENCES'}: continue
    current_name=name; current_spec=None
    records.append((current_name,None,current_level,current_mode))
# De-duplicate exact repeated records caused by page continuation, retaining order.
seen=set(); clean=[]
for rec in records:
    if rec in seen: continue
    seen.add(rec); clean.append(rec)
records=clean
# External AMU centres are not part of the Aligarh campus scope.
records=[r for r in records if 'at AMU Centre,' not in r[0]]
# read career tree read-only and build root-first breadcrumb
con=sqlite3.connect(f'file:{db_path}?mode=ro',uri=True)
rows=con.execute('''WITH RECURSIVE tree(id,slug,name,parent_id,stream_id,path) AS (
 SELECT id,slug,name,parent_id,stream_id,name FROM career_nodes WHERE parent_id IS NULL
 UNION ALL SELECT c.id,c.slug,c.name,c.parent_id,c.stream_id,tree.path || ' > ' || c.name
 FROM career_nodes c JOIN tree ON c.parent_id=tree.id)
 SELECT id,slug,path FROM tree''').fetchall()
nodes={slug:(i,slug,path) for i,slug,path in rows}

def node(slug,relation='nearest-parent',confidence='medium'):
    i,s,p=nodes[slug]
    return {'career_node_id':i,'career_node_slug':s,'career_breadcrumb':p,'relation':relation,'confidence':confidence,'mapping_status':'reviewed_against_local_tree'}

