        if 'mathematics' in s: return node('bsc_maths','direct','high')
        if 'geology' in s: return node('bsc_geology','direct','high')
        if 'computer science' in s or 'computer science and applications' in s: return node('bsc_cs','closest-specialization','high')
        if 'geography' in s: return node('science_common','nearest-parent','medium')
